 comparison","version":1,"x-agent-authoring":{"generationDefault":1,"origin":"independent-first-party","reviewState":"owner-requested-original-authoring"},"x-discovery":{"badges":["Needs 1 photo","Keeps source identity","Makes 1 image"],"collection":"original-systems","complexity":"guided","inputModes":["single-image"],"inputSummary":["One photo and a creative direction"],"intentAliases":["pastel city comparison","two color versions of city","paired urban palette"],"intents":["edit"],"outputKinds":["image"],"preservationNeeds":["identity","composition"],"requiredInputSummary":["One source image and a short direction"],"subjectKinds":["person","object","place","concept"],"thumbnail":{"alt":"First-party graphic preview for City palette comparison, illustrating paired color interpretation.","src":"/recipe-thumbnails/original-systems/city-palette-comparison.svg"},"userPromise":"Create two coordinated interpretations of a city photo with distinct pastel atmospheres."},"x-presentation":{"advancedControlIds":[],"initialView":"canvas","primaryControlIds":["brief","method","structure","aspect-ratio"],"resultEmphasis":"hero","showPromptByDefault":false}}', 'prompt-canvas.prompt-workspace-template@2', 'sha256:d6833fdd1de9bced19dff89c7c562d579d5f3b33d489b209db4bc93dd7a0843e', 'Create two coordinated interpretations of a city photo with distinct pastel atmospheres. Using the source image as factual ground truth, create an original transformation for {{brief}}. Use {{method}} as the visual method. Organize the image so {{structure}}. Favor one clear focal idea, intentional negative space, coherent lighting, believable depth, and material-specific detail. Do not add unrelated text, logos, watermarks, copied characters, or unsupported factual claims.', NULL, '{"creator":"Prompt Canvas","kind":"first-party","notes":"Independently authored for Prompt Canvas from a high-level creative use case.","promptUsage":"original","title":"City palette comparison"}', 'Initial official catalog publication.', '2026-09-03T00:00:00Z', '2026-09-03T00:00:00Z');
