 idea, intentional negative space, coherent lighting, believable depth, and material-specific detail. Do not add unrelated text, logos, watermarks, copied characters, or unsupported factual claims.","title":"Creative direction","variables":[{"defaultValue":"A messenger entering a city grown through the ribs of a cloud creature","id":"brief","label":"Creative brief","required":true,"type":"text"},{"defaultValue":"human scale against colossus","id":"method","label":"Visual method","type":"string"},{"defaultValue":"layered occlusion and atmosphere lock the scale","id":"structure","label":"Composition rule","type":"string"}]},"schema":"prompt-canvas.prompt-workspace-template@2","source":{"creator":"Prompt Canvas","kind":"first-party","notes":"Independently authored for Prompt Canvas from a high-level creative use case.","promptUsage":"original","title":"Colossal realm scale"},"status":"starter","tags":["illustration story","tiny person giant world","colossal fantasy landscape"],"thumbnail":{"alt":"First-party graphic preview for Colossal realm scale, illustrating human scale against colossus.","assetPath":"/recipe-thumbnails/original-systems/colossal-realm-scale.svg"},"title":"Colossal realm scale","version":1,"x-agent-authoring":{"generationDefault":1,"origin":"independent-first-party","reviewState":"owner-requested-original-authoring"},"x-discovery":{"badges":["No photo needed","Makes 1 image"],"collection":"original-systems","complexity":"guided","inputModes":["text"],"inputSummary":["A creative brief"],"intentAliases":["tiny person giant world","colossal fantasy landscape","impossible scale scene"],"intents":["create"],"outputKinds":["image"],"preservationNeeds":[],"requiredInputSummary":["A short creative brief"],"subjectKinds":["person","object","place","concept"],"thumbnail":{"alt":"First-party graphic preview for Colossal realm scale, illustrating human scale against colossus.","src":"/recipe-thumbnails/original-systems/colossal-realm-scale.svg"},"userPromise":"